<?php
namespace CloudHost247\Ovh\Pricing;use WHMCS\Database\Capsule;use InvalidArgumentException;
final class PricingService
{private$calc;function __construct(PriceCalculator$c){$this->calc=$c;}function preview($mappingId,$currencyId,$cycle,$sourcePrice,$sourceCurrency,$rounding='nearest',$precision=2){$cycles=array('monthly','quarterly','semiannually','annually','biennially','triennially');if(!in_array($cycle,$cycles,true))throw new InvalidArgumentException('Unsupported billing cycle.');$m=Capsule::table('mod_cloudhost247_ovh_product_mappings')->where('id',(int)$mappingId)->first();$target=Capsule::table('tblcurrencies')->where('id',(int)$currencyId)->first();$source=Capsule::table('tblcurrencies')->where('code',strtoupper($sourceCurrency))->first();if(!$m||!$target||!$source)throw new InvalidArgumentException('Mapping or currency is unavailable.');$final=$this->calc->calculate($sourcePrice,$source->rate,$target->rate,$m->margin_percent,$precision,$rounding);$id=Capsule::table('mod_cloudhost247_ovh_price_previews')->insertGetId(array('mapping_id'=>$m->id,'whmcs_currency_id'=>$target->id,'billing_cycle'=>$cycle,'source_price'=>$sourcePrice,'source_currency'=>$source->code,'conversion_rate'=>$target->rate/$source->rate,'margin_percent'=>$m->margin_percent,'rounding_mode'=>$rounding,'final_price'=>$final,'status'=>'preview','admin_id'=>$_SESSION['adminid']??null,'created_at'=>date('Y-m-d H:i:s')));return array('id'=>$id,'source_price'=>(float)$sourcePrice,'source_currency'=>$source->code,'conversion_rate'=>$target->rate/$source->rate,'margin'=>(float)$m->margin_percent,'rounding'=>$rounding,'final_price'=>$final,'target_currency'=>$target->code);}
 function apply($previewId,$confirmed){if(!$confirmed)throw new InvalidArgumentException('Explicit pricing confirmation is required.');return Capsule::connection()->transaction(function()use($previewId){$p=Capsule::table('mod_cloudhost247_ovh_price_previews')->where('id',(int)$previewId)->where('status','preview')->lockForUpdate()->first();if(!$p)throw new InvalidArgumentException('Unused preview not found.');$m=Capsule::table('mod_cloudhost247_ovh_product_mappings')->where('id',$p->mapping_id)->first();$pricing=Capsule::table('tblpricing')->where('type','product')->where('relid',$m->whmcs_product_id)->where('currency',$p->whmcs_currency_id)->first();if(!$pricing)throw new InvalidArgumentException('WHMCS pricing row does not exist; it will not be created silently.');$before=$pricing->{$p->billing_cycle};Capsule::table('tblpricing')->where('id',$pricing->id)->update(array($p->billing_cycle=>$p->final_price));Capsule::table('mod_cloudhost247_ovh_price_previews')->where('id',$p->id)->update(array('status'=>'applied','applied_at'=>date('Y-m-d H:i:s')));Capsule::table('mod_cloudhost247_ovh_audit')->insert(array('admin_id'=>$_SESSION['adminid']??null,'action'=>'price.apply','target_type'=>'product','target_id'=>$m->whmcs_product_id,'before_json'=>json_encode(array($p->billing_cycle=>$before)),'after_json'=>json_encode(array($p->billing_cycle=>$p->final_price)),'created_at'=>date('Y-m-d H:i:s')));return$p->final_price;});}}
